      "answer": "The LORD is One",
      "whyWrong": {
        "The LORD is hidden": "The LORD is not hidden; Moses says He is “among you” (6:15) and has acted openly before Israel’s eyes (6:22).",
        "The LORD sleeps not": "God’s watchfulness is taught elsewhere (Psalm 121:4), but the declaration in 6:4 is that the LORD is One.",
        "The LORD changes not": "God’s unchanging nature is stated in Malachi 3:6; the declaration “Hear, O Israel” in 6:4 is about His oneness.",
        "The LORD is far off": "Far from being distant, the LORD is described as dwelling “among you” (6:15), and the Shema stresses that He is One."
      },
      "explanation": "The Shema declares, “The LORD our God, the LORD is One” (6:4).",
